    '"', ",", "\n", "\r\n", " ", "\t", "\u00a0", "\u200b", "\u0301", "\ufeff",
    "-", "+", "_", ".", "0", "1", "9", "999", "1000", "\u0661", "W", "T",
    "a", "A", "é", "É", "Liverpool", "liverpool", "1974-08-17", "1974-02-30",
]  # fmt: skip


def mutate_text(text: str, rng: random.Random) -> bytes:
